364.   private void setScrapeTimestamp(Metrics.Metric.Builder metricBuilder, DataPointSnapshot data) {
365.     if (data.hasScrapeTimestamp()) {
366.       metricBuilder.setTimestampMs(data.getScrapeTimestampMillis());
367.     }
368.   }
